import React, { useState } from "react";

function App() {
  const [formData, setFormData] = useState({
    nombre: "",
    email: "",
    telefono: "",
    edad: "",
    ocupacion: "",
    cursoId: ""
  });

  const [totalAmount, setTotalAmount] = useState(100); // El monto a pagar

  // Manejar cambios en los inputs
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  // Enviar los datos al backend para la inscripción
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:3001/api/usuarios/inscribirse", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(formData)
      });

      const data = await response.json();

      if (response.ok) {
        alert("¡Inscripción exitosa!");
        console.log(data);

        // Si la inscripción es exitosa, crear la orden de pago con PayPal
        const paymentResponse = await fetch("http://localhost:3001/api/pagos/realizar", {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            inscripcionId: data.inscripcion.id, // ID de la inscripción
            metodo: 'paypal',
            totalAmount: totalAmount
          })
        });

        const paymentData = await paymentResponse.json();

        if (paymentResponse.ok) {
          // Redirigir a PayPal para que complete el pago
          window.location.href = `https://www.paypal.com/checkoutnow?token=${paymentData.id}`;
        } else {
          alert("Error al crear el pago");
          console.error(paymentData);
        }
      } else {
        alert("Error en la inscripción");
        console.error(data);
      }
    } catch (error) {
      console.error("Error al conectar con el servidor:", error);
    }
  };

  // Confirmar el pago luego de ser redirigido por PayPal
  const handleConfirmPayment = async (orderId) => {
    try {
      const response = await fetch(`http://localhost:3001/api/pagos/confirmar/${orderId}`, {
        method: "GET",
      });

      const data = await response.json();

      if (response.ok) {
        alert("Pago confirmado con éxito");
        console.log(data);
      } else {
        alert("Error al confirmar el pago");
        console.error(data);
      }
    } catch (error) {
      console.error("Error al conectar con el servidor:", error);
    }
  };

  return (
    <div>
      <h2>Inscribirse en un curso</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="nombre"
          placeholder="Nombre"
          onChange={handleChange}
          required
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="telefono"
          placeholder="Teléfono"
          onChange={handleChange}
          required
        />
        <input
          type="number"
          name="edad"
          placeholder="Edad"
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="ocupacion"
          placeholder="Ocupación"
          onChange={handleChange}
          required
        />
        <input
          type="number"
          name="cursoId"
          placeholder="ID del curso"
          onChange={handleChange}
          required
        />
        <button type="submit">Inscribirse</button>
      </form>

      {/* Simulación de confirmación de pago */}
      <button onClick={() => handleConfirmPayment("orderId_example")}>Confirmar Pago</button>
    </div>
  );
}

export default App;
